// Validate + normalise the brief coming from the webhook
const b = $json.body || $json;
const idea = String(b.idea || '').trim().slice(0, 600);
if (idea.length < 8) throw new Error('idea is required (8+ characters)');
const duration = [15, 30, 60].includes(Number(b.duration)) ? Number(b.duration) : 30;
const aspect = ['9:16', '16:9', '1:1'].includes(b.aspect) ? b.aspect : '16:9';
const brand = String(b.brand || '').slice(0, 80);
const mood = String(b.mood || 'cinematic').slice(0, 40);
const style = String(b.style || 'cinematic realism').slice(0, 40);
const project = String(b.project || `${brand || 'Untitled'} ${duration}s ${aspect}`).slice(0, 120);
const prompt = `You are a senior commercial director and AI video prompt engineer.
Create a storyboard as STRICT JSON for: idea "${idea}", brand "${brand}", mood ${mood}, style ${style}, total ${duration}s (shot durations MUST sum to ${duration}), aspect ${aspect}.
Return { "title", "logline", "bible": { "subject","character","wardrobe","setting","palette":[3 hex],"lighting","lensPackage","grade","negative","consistencyTokens" },
"shots": [ { "beat":"Hook|Build|Turn|Reveal|CTA", "duration", "camera", "lens", "lighting", "action", "transition", "sfx", "music", "vo",
"prompts": { "kling", "sora", "veo", "keyframe" } } ] }.
Kling = concise subject/action/scene/camera/lighting/style + Negative line. Sora = cinematic prose. Veo = labelled lines incl. Audio. Keyframe = still image prompt for Nanobanana/Krea.`;
return [{ json: { idea, brand, mood, style, duration, aspect, project, prompt } }];

// Parse Gemini JSON and turn every shot into one sheet row
const brief = $('Validate brief').first().json;
const text = $json.candidates?.[0]?.content?.parts?.map(p => p.text).join('') || '{}';
let sb;
try { sb = JSON.parse(text); } catch (e) { throw new Error('Gemini did not return valid JSON'); }
const shots = Array.isArray(sb.shots) ? sb.shots : [];
if (!shots.length) throw new Error('No shots returned');
// rescale durations so they sum exactly to the target (0.5s steps)
const sum = shots.reduce((a, s) => a + (Number(s.duration) || 1), 0);
let t = 0;
const createdAt = new Date().toISOString();
return shots.map((s, i) => {
  let d = Math.max(0.5, Math.round(((Number(s.duration) || 1) / sum) * brief.duration * 2) / 2);
  if (i === shots.length - 1) d = Math.max(0.5, Math.round((brief.duration - t) * 10) / 10);
  const row = {
    'Project': brief.project,
    'Title': sb.title || '',
    'Shot': i + 1,
    'Beat': s.beat || '',
    'Start (s)': Math.round(t * 10) / 10,
    'Duration (s)': d,
    'Camera': s.camera || '',
    'Lens': s.lens || '',
    'Lighting': s.lighting || '',
    'Action': s.action || '',
    'Transition': s.transition || '',
    'SFX': s.sfx || '',
    'Music': s.music || '',
    'VO': s.vo || '',
    'Kling Prompt': s.prompts?.kling || '',
    'Sora Prompt': s.prompts?.sora || '',
    'Veo Prompt': s.prompts?.veo || '',
    'Keyframe Prompt': s.prompts?.keyframe || '',
    'Consistency Tokens': sb.bible?.consistencyTokens || '',
    'Aspect': brief.aspect,
    'Status': 'To generate',
    'Created At': createdAt,
  };
  t += d;
  return { json: row };
});

// One summary item for the webhook response
const rows = $('Split shots to rows').all().map(i => i.json);
return [{ json: {
  ok: true,
  project: rows[0]?.Project,
  title: rows[0]?.Title,
  shots: rows.length,
  totalSeconds: Math.round(rows.reduce((a, r) => a + Number(r['Duration (s)']), 0) * 10) / 10,
  sheet: `https://docs.google.com/spreadsheets/d/${$env.STORYBOARD_SHEET_ID}`,
} }];
